        self.run_c('8001EB10','\nVoiceState D_8004BEB8[4];SequenceNode nodes[5];SequenceNode *D_80050C50,*D_80050C54;static u32 id,parent,child;static int calls;\nvoid func_80021844(VoiceState *s){assert(s==D_8004BEB8+1);calls++;s->identifier60=id;s->parent14=parent;s->child10=child;s->entry18=nodes+1;s->unknown00[0]=42;}\nint main(void){VoiceState expected[4];SequenceNode en[5];SequenceNode *used,*freehead;int valid,p,c,prev,next,free,i;for(valid=0;valid<2;valid++)for(p=0;p<2;p++)for(c=0;c<2;c++)for(prev=0;prev<2;prev++)for(next=0;next<2;next++)for(free=0;free<2;free++){memset(D_8004BEB8,0xA5,sizeof(D_8004BEB8));memset(nodes,0,sizeof(nodes));for(i=0;i<5;i++){nodes[i].key=100+i;nodes[i].value=200+i;}nodes[1].previous=prev?nodes:0;nodes[1].next=next?nodes+2:0;nodes[0].next=nodes+1;nodes[2].previous=nodes+1;nodes[3].next=nodes+4;nodes[4].previous=nodes+3;D_80050C50=prev?nodes:nodes+1;D_80050C54=free?nodes+3:0;id=valid?0xABCDEF01U:0xFFFFFFFFU;parent=p?0xABCDEF00U:0xFFFFFFFFU;child=c?0xABCDEF02U:0xFFFFFFFFU;memcpy(expected,D_8004BEB8,sizeof(expected));memcpy(en,nodes,sizeof(en));expected[1].identifier60=id;expected[1].parent14=parent;expected[1].child10=child;expected[1].entry18=nodes+1;expected[1].unknown00[0]=42;used=D_80050C50;freehead=D_80050C54;if(valid){if(p){expected[0].child10=child;if(c)expected[2].parent14=parent;}else if(c){en[1].value=child;expected[2].parent14=0xFFFFFFFFU;expected[2].entry18=nodes+1;}else{if(prev)en[0].next=next?nodes+2:0;else used=next?nodes+2:0;if(next)en[2].previous=prev?nodes:0;en[1].next=freehead;if(free)en[3].previous=nodes+1;en[1].previous=0;freehead=nodes+1;}}calls=0;func_8001EB10(D_8004BEB8+1);assert(calls==1&&memcmp(expected,D_8004BEB8,sizeof(expected))==0&&memcmp(en,nodes,sizeof(en))==0&&D_80050C50==used&&D_80050C54==freehead);}return 0;}\n',True)
